<?php require_once __DIR__ . '/../cdn.php'; \SimpleCdn\Cdn::enable([]); $nodesFile = __DIR__ . '/../nodes.json'; $cdnNodes = []; if (is_file($nodesFile)) { $content = @file_get_contents($nodesFile); if ($content !== false) { $decoded = @json_decode($content, true); if (is_array($decoded)) { $cdnNodes = $decoded; } } } $warmUrls = \SimpleCdn\Cdn::getCacheWarmerUrls(); $healthStatuses = \SimpleCdn\Cdn::getHealthStatus(); $warmLogs = \SimpleCdn\Cdn::getWarmLogs(50); $warmResult = null; if (session_status() === PHP_SESSION_NONE) { session_start(); } if (!empty($_SESSION['warm_result'])) { $warmResult = $_SESSION['warm_result']; unset($_SESSION['warm_result']); } $message = ''; $messageType = 'info'; if ($_SERVER['REQUEST_METHOD'] === 'POST') { $action = $_POST['action'] ?? ''; if ($action === 'save_urls') { $newUrls = []; $urlList = $_POST['warm_url'] ?? []; $nameList = $_POST['warm_name'] ?? []; $enabledList = $_POST['warm_enabled'] ?? []; foreach ($urlList as $i => $url) { $url = trim($url); if ($url === '') { continue; } $newUrls[] = [ 'url' => $url, 'name' => trim($nameList[$i] ?? ''), 'enabled' => isset($enabledList[$i]) && $enabledList[$i] === '1', ]; } if (\SimpleCdn\Cdn::setCacheWarmerUrls($newUrls)) { $warmUrls = $newUrls; $message = '预热URL配置已保存'; $messageType = 'success'; } else { $message = '保存失败，请检查写权限'; $messageType = 'error'; } } if ($action === 'warm_now') { $warmResult = \SimpleCdn\Cdn::warmCacheAfterPurge(); $message = '预热完成：共 ' . $warmResult['total'] . ' 个请求，成功 ' . $warmResult['success'] . ' 个，失败 ' . $warmResult['failed'] . ' 个'; $messageType = $warmResult['failed'] > 0 ? 'warn' : 'success'; $warmLogs = \SimpleCdn\Cdn::getWarmLogs(50); } if ($action === 'delete_url') { $index = (int) ($_POST['url_index'] ?? -1); if (isset($warmUrls[$index])) { array_splice($warmUrls, $index, 1); if (\SimpleCdn\Cdn::setCacheWarmerUrls($warmUrls)) { $message = '预热URL已删除'; $messageType = 'success'; } else { $message = '删除失败'; $messageType = 'error'; } } else { $message = 'URL不存在'; $messageType = 'error'; } } } ?> <!DOCTYPE html> <html lang="zh-CN"> <head> <meta charset="UTF-8"> <meta name="viewport" content="width=device-width, initial-scale=1.0"> <title>Simple CDN 后台 - 缓存预热管理</title> <style> * { box-sizing: border-box; } body { font-family: system-ui, -apple-system, Segoe UI, Microsoft YaHei, sans-serif; background: #f5f7fa; color: #111; margin: 0; } .topbar { background: #fff; border-bottom: 1px solid #e2e8f0; padding: 12px 24px; display: flex; align-items: center; gap: 16px; } .topbar h1 { font-size: 16px; margin: 0; color: #0f172a; } .topbar a { color: #2563eb; text-decoration: none; font-size: 13px; } .topbar a:hover { text-decoration: underline; } .topbar .spacer { flex: 1; } .container { max-width: 1200px; margin: 24px auto; padding: 0 20px; } .card { background: #fff; border: 1px solid #e2e8f0; border-radius: 10px; padding: 20px; margin-bottom: 20px; } .card h2 { font-size: 18px; margin: 0 0 16px; color: #0f172a; } .msg { padding: 10px 16px; border-radius: 6px; margin-bottom: 16px; font-size: 14px; } .msg.info { background: #dbeafe; color: #1e40af; border: 1px solid #bfdbfe; } .msg.error { background: #fee2e2; color: #991b1b; border: 1px solid #fecaca; } .msg.success { background: #dcfce7; color: #166534; border: 1px solid #86efac; } .msg.warn { background: #fef3c7; color: #92400e; border: 1px solid #fde68a; } .btn { display: inline-block; padding: 8px 14px; border: none; border-radius: 6px; font-size: 13px; cursor: pointer; text-decoration: none; } .btn:hover { opacity: 0.9; } .btn-primary { background: #2563eb; color: #fff; } .btn-primary:hover { background: #1d4ed8; } .btn-secondary { background: #f1f5f9; color: #334155; } .btn-secondary:hover { background: #e2e8f0; } .btn-success { background: #059669; color: #fff; } .btn-success:hover { background: #047857; } .btn-danger { background: #dc2626; color: #fff; } .btn-danger:hover { background: #b91c1c; } .btn-sm { padding: 4px 8px; font-size: 12px; } .btn-group { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 16px; } .form-row { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 12px; margin-bottom: 12px; } .form-group { display: flex; flex-direction: column; } .form-group label { font-size: 13px; color: #64748b; margin-bottom: 4px; } .form-group input { padding: 8px; border: 1px solid #e2e8f0; border-radius: 6px; font-size: 13px; } .form-group.full { grid-column: 1 / -1; } .checkbox-group { display: flex; align-items: center; gap: 8px; margin-top: 22px; } .checkbox-group input { width: 18px; height: 18px; } .table { width: 100%; border-collapse: collapse; margin-top: 12px; } .table th { text-align: left; padding: 10px 12px; font-size: 13px; color: #64748b; border-bottom: 1px solid #f1f5f9; background: #fafbfc; } .table td { padding: 10px 12px; border-bottom: 1px solid #f1f5f9; font-size: 14px; } .table tr:hover { background: #f8fafc; } .badge { display: inline-block; padding: 2px 8px; border-radius: 10px; font-size: 11px; font-weight: 700; } .badge-online { background: #dcfce7; color: #166534; } .badge-offline { background: #fee2e2; color: #991b1b; } .badge-unknown { background: #f1f5f9; color: #64748b; } .badge-success { background: #dcfce7; color: #166534; } .badge-fail { background: #fee2e2; color: #991b1b; } .muted { color: #64748b; font-size: 13px; } .empty { color: #94a3b8; font-style: italic; } .stat-card { background: #fff; border: 1px solid #e2e8f0; border-radius: 10px; padding: 16px; } .stat-card .value { font-size: 30px; font-weight: 700; } .stat-card .label { font-size: 13px; color: #64748b; margin-top: 4px; } .note { font-size: 13px; color: #64748b; margin-top: 16px; } </style> </head> <body> <div class="topbar"> <h1>缓存预热管理</h1> <div class="spacer"></div> <a href="index.php" class="btn-secondary">← 返回仪表盘</a> </div> <div class="container"> <?php if ($message): ?> <div class="msg <?php echo $messageType === 'success' ? 'success' : ($messageType === 'error' ? 'error' : 'info'); ?>"><?php echo htmlspecialchars($message); ?></div> <?php endif; ?> <?php if ($warmResult): ?> <div class="msg info"> <strong>本次预热结果</strong>：共 <?php echo number_format($warmResult['total']); ?> 个请求，成功 <span class="badge-success"><?php echo number_format($warmResult['success']); ?></span> 个，失败 <span class="badge-fail"><?php echo number_format($warmResult['failed']); ?></span> 个 </div> <?php endif; ?> <div class="card"> <h2>1. 预热URL配置</h2> <p class="note">配置需要预热的URL。清理缓存后，系统会自动将这些URL预热到各CDN节点，避免首次访问回源。</p> <form method="POST" action=""> <input type="hidden" name="action" value="save_urls"> <div class="form-row"> <div class="form-group full"> <label>预热URL列表（每行一个URL，可选名称：URL|名称）</label> <textarea name="warm_urls_text" rows="6" placeholder="https://cdn.example.com/index.php|首页 https://cdn.example.com/img/banner.jpg|横幅图片"><?php foreach ($warmUrls as $u) { echo htmlspecialchars($u['url'] ?? '') . '|' . htmlspecialchars($u['name'] ?? '') . "\n"; } ?></textarea> <div class="muted">格式：URL|名称（名称可选）。每行一个。</div> </div> </div> <div class="checkbox-group"> <input type="checkbox" name="warm_enable" value="1" id="warm_enable" <?php echo !empty(self::$config['cache_warm_enable'] ?? true) ? 'checked' : ''; ?>> <label for="warm_enable">启用自动预热（清理缓存后自动预热）</label> </div> <button type="submit" class="btn btn-primary">保存配置</button> </form> </div> <div class="card"> <h2>2. 手动预热</h2> <div class="btn-group"> <form method="POST" action="" style="margin:0;" onsubmit="return confirm('确定要立即对所有在线节点预热所有配置的URL吗？');"> <button type="submit" name="action" value="warm_now" class="btn btn-success">立即预热所有节点</button> </form> <a href="health.php" class="btn btn-secondary btn-sm">查看节点健康状态</a> </div> <div class="note"> <strong>预热机制</strong>：系统会向每个在线节点发送带 <code>__cdn_warm=1</code> 标记的请求，节点会回源抓取并缓存内容。<br> 离线节点会被自动跳过。预热结果会记录在预热日志中。 </div> </div> <?php if (!empty($warmLogs)): ?> <div class="card"> <h2>3. 预热日志（最近 <?php echo count($warmLogs); ?> 条）</h2> <table class="table"> <thead> <tr> <th style="width:16%;">时间</th> <th style="width:12%;">总请求</th> <th style="width:12%;">成功</th> <th style="width:12%;">失败</th> <th style="width:auto;">节点详情</th> </tr> </thead> <tbody> <?php foreach ($warmLogs as $log): ?> <tr> <td><?php echo htmlspecialchars($log['time'] ?? ''); ?></td> <td><?php echo number_format($log['total'] ?? 0); ?></td> <td><span class="badge-success"><?php echo number_format($log['success'] ?? 0); ?></span></td> <td><span class="badge-fail"><?php echo number_format($log['failed'] ?? 0); ?></span></td> <td> <?php $details = $log['details'] ?? []; if (empty($details)) { echo '<span class="muted">无详情</span>'; } else { foreach ($details as $d) { $statusClass = $d['status'] === 'success' ? 'badge-success' : ($d['status'] === 'failed' ? 'badge-fail' : 'badge-unknown'); echo '<span class="badge ' . $statusClass . '">' . htmlspecialchars($d['status'] ?? '') . '</span>'; echo '<span class="muted" style="font-size:11px;"> ' . htmlspecialchars($d['node_name'] ?? '') . '</span>'; if (!empty($d['message'])) { echo '<br><span class="muted" style="font-size:11px;">' . htmlspecialchars($d['message']) . '</span>'; } } } ?> </td> </tr> <?php endforeach; ?> </tbody> </table> <?php endif; ?> </div> </div> </body> </html>;